function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}

const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};

function readHeader(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return null;
}

const expectedToken = env('RENOV_INTERNAL_TOKEN');

if (!expectedToken) {
  return [{ json: { authorized: false, statusCode: 503, error: 'RENOV_INTERNAL_TOKEN no está configurado en n8n.' } }];
}

const bearer = readHeader('authorization') || '';
const provided = readHeader('x-internal-token')
  || (bearer.startsWith('Bearer ') ? bearer.slice(7).trim() : '');

if (provided !== expectedToken) {
  return [{ json: { authorized: false, statusCode: 401, error: 'Token interno inválido o ausente.' } }];
}

// Which lock, and whose. Releasing is deliberately explicit: either name the
// execution that holds it, or pass force to clear whoever holds it.
const ALLOWED_LOCKS = ['OPS-04:renovation_dev', 'OPS-04:renovation_uat', 'OPS-04:renovation'];
const lockName = String(body.lock_name || 'OPS-04:renovation_dev');

if (!ALLOWED_LOCKS.includes(lockName)) {
  return [{ json: { authorized: false, statusCode: 400, error: 'lock_name fuera de la lista permitida: ' + ALLOWED_LOCKS.join(', ') } }];
}

const owner = body.owner === undefined || body.owner === null ? null : String(body.owner);
const force = body.force === true;

if (!owner && !force) {
  return [{ json: { authorized: false, statusCode: 400, error: 'Indica "owner" (el id de ejecución que dejó el lock tomado) o "force": true.' } }];
}

return [{
  json: {
    authorized: true,
    statusCode: 200,
    lock_name: lockName,
    owner: owner,
    force: force,
  },
}];
